APP_DIR = Path(__file__).resolve().parent
MAX_SIDE = int(os.environ.get("FASTHDR_MAX_SIDE", "1600"))
JPEG_QUALITY = int(os.environ.get("FASTHDR_JPEG_QUALITY", "93"))
cv2.setNumThreads(1)

