app.config["MAX_CONTENT_LENGTH"] = 6 * 1024 * 1024 * 1024

LOGO_HEADER_URI = "data:image/webp;base64,"
LOGO_FAVICON_URI = "data:image/png;base64,"

LOGO_PNG_B64 = ""
LOGO_HEADER_URI = "/colora-logo.png"
LOGO_FAVICON_URI = "/colora-logo.png"


@dataclass
class PhotoFile:
    name: str
    storage: Any


@dataclass
class HdrSet:
    name: str
    low: PhotoFile
    mid: PhotoFile
    high: PhotoFile


def luminance(bgr: np.ndarray) -> np.ndarray:
    b, g, r = cv2.split(bgr.astype(np.float32) / 255.0)
    return 0.0722 * b + 0.7152 * g + 0.2126 * r


def smoothstep(edge0: float, edge1: float, value: np.ndarray) -> np.ndarray:
    x = np.clip((value - edge0) / max(1e-6, edge1 - edge0), 0, 1)
    return x * x * (3 - 2 * x)


def to_u8(image: np.ndarray) -> np.ndarray:
    return np.clip(image * 255.0 + 0.5, 0, 255).astype(np.uint8)


def decode_photo(photo: PhotoFile) -> np.ndarray:
    photo.storage.stream.seek(0)
    raw = np.frombuffer(photo.storage.read(), dtype=np.uint8)
    image = cv2.imdecode(raw, cv2.IMREAD_COLOR)
    del raw
    if image is None:
        raise ValueError(f"{photo.name} okunamadi")

    h, w = image.shape[:2]
    scale = min(1.0, MAX_SIDE / max(h, w))
    if scale < 1:
        image = cv2.resize(image, (round(w * scale), round(h * scale)), interpolation=cv2.INTER_AREA)
    return image


def exposure_label(name: str) -> str | None:
    lower = name.lower()
    if re.search(r"(^|[^a-z])(low|under|dark|dusuk)([^a-z]|$)", lower):
        return "low"
    if re.search(r"(^|[^a-z])(mid|middle|normal|orta)([^a-z]|$)", lower):
        return "mid"
    if re.search(r"(^|[^a-z])(high|over|bright|yuksek)([^a-z]|$)", lower):
        return "high"
    return None


def scene_key(name: str) -> str:
    key = re.sub(r"\.[^.]+$", "", name)
    key = re.sub(r"(^|[^a-z])(low|under|dark|dusuk|mid|middle|normal|orta|high|over|bright|yuksek)([^a-z]|$)", "_", key, flags=re.I)
    key = re.sub(r"[_\s-]+", "_", key).strip("_")
    return re.sub(r"[^a-z0-9_-]+", "_", key, flags=re.I) or "scene"


def sort_photos(photos: list[PhotoFile]) -> list[PhotoFile]:
    return sorted(photos, key=lambda item: item.name.lower())


def group_photos(photos: list[PhotoFile]) -> list[HdrSet]:
    photos = sort_photos(photos)
    named: dict[str, dict[str, PhotoFile]] = {}
    has_all_labels = True

    for photo in photos:
        label = exposure_label(photo.name)
        if label is None:
            has_all_labels = False
            break
        named.setdefault(scene_key(photo.name), {})[label] = photo

    if has_all_labels:
        groups = []
        for key in sorted(named.keys()):
            item = named[key]
            if {"low", "mid", "high"} <= set(item.keys()):
                groups.append(HdrSet(key, item["low"], item["mid"], item["high"]))
        if groups:
            return groups

    groups = []
    for index in range(0, len(photos) - 2, 3):
        low, mid, high = photos[index : index + 3]
        groups.append(HdrSet(scene_key(mid.name), low, mid, high))
    return groups


def order_by_brightness(images: list[np.ndarray]) -> tuple[np.ndarray, np.ndarray, np.ndarray]:
    scored = sorted(((float(luminance(img).mean()), img) for img in images), key=lambda item: item[0])
    return scored[0][1], scored[1][1], scored[2][1]


def match_dimensions(images: list[np.ndarray]) -> list[np.ndarray]:
    ref_h, ref_w = images[1].shape[:2]
    matched = []
    for image in images:
        h, w = image.shape[:2]
        if h == ref_h and w == ref_w:
            matched.append(image)
            continue
        interpolation = cv2.INTER_AREA if h * w > ref_h * ref_w else cv2.INTER_CUBIC
        matched.append(cv2.resize(image, (ref_w, ref_h), interpolation=interpolation))
    return matched


def trim_shift_edges(images: list[np.ndarray], ratio: float = 0.035) -> list[np.ndarray]:
    h, w = images[0].shape[:2]
    crop_x = max(1, int(w * ratio))
    crop_y = max(1, int(h * ratio))
    if crop_x * 2 >= w or crop_y * 2 >= h:
        return images

    trimmed = []
    for image in images:
        crop = image[crop_y : h - crop_y, crop_x : w - crop_x]
        trimmed.append(cv2.resize(crop, (w, h), interpolation=cv2.INTER_CUBIC))
    return trimmed


def align_images(images: list[np.ndarray]) -> list[np.ndarray]:
    aligned = [img.copy() for img in images]
    try:
        align = cv2.createAlignMTB(max_bits=6, exclude_range=4, cut=True)
        result: list[np.ndarray] = []
        align.process(aligned, result)
        if len(result) == 3:
            return result
    except Exception:
        pass
    return aligned


def gray_world(image: np.ndarray, strength: float = 0.18) -> np.ndarray:
    arr = image.astype(np.float32)
    means = arr.reshape(-1, 3).mean(axis=0)
    target = means.mean()
    gain = target / np.maximum(means, 1)
    gain = 1 + (gain - 1) * strength
    return np.clip(arr * gain, 0, 255).astype(np.uint8)


def auto_levels_rgb(image: np.ndarray, low_pct: float = 0.25, high_pct: float = 99.82) -> np.ndarray:
    flat = image.reshape(-1, 3)
    low = np.percentile(flat, low_pct, axis=0)
    high = np.percentile(flat, high_pct, axis=0)
    return np.clip((image - low) / np.maximum(high - low, 1e-4), 0, 1)


def local_contrast_bgr(image: np.ndarray, clip_limit: float = 1.7) -> np.ndarray:
    lab = cv2.cvtColor(image, cv2.COLOR_BGR2LAB)
    l, a, b = cv2.split(lab)
    clahe = cv2.createCLAHE(clipLimit=clip_limit, tileGridSize=(8, 8))
    l2 = clahe.apply(l)
    l = cv2.addWeighted(l, 0.52, l2, 0.48, 0)
    return cv2.cvtColor(cv2.merge([l, a, b]), cv2.COLOR_LAB2BGR)


def cinematic_vibrance_bgr(image: np.ndarray, strength: float = 0.34) -> np.ndarray:
    hsv = cv2.cvtColor(image, cv2.COLOR_BGR2HSV).astype(np.float32)
    sat = hsv[..., 1] / 255.0
    val = hsv[..., 2] / 255.0
    boost = 1 + strength * (1 - sat) * (0.35 + 0.65 * smoothstep(0.08, 0.92, val))
    hsv[..., 1] = np.clip(hsv[..., 1] * boost, 0, 255)
    hsv[..., 2] = np.clip(hsv[..., 2] * 1.015, 0, 255)
    return cv2.cvtColor(hsv.astype(np.uint8), cv2.COLOR_HSV2BGR)


def blend_window(base: np.ndarray, dark: np.ndarray, mid: np.ndarray, amount: float = 0.86) -> np.ndarray:
    mid_y = luminance(mid)
    dark_y = luminance(dark)
    mask = np.clip((mid_y - 0.70) / 0.24, 0, 1)
    recoverable = np.clip((0.92 - dark_y) / 0.18, 0, 1)
    mask = cv2.GaussianBlur(np.clip(mask * recoverable, 0, 1), (0, 0), 7)

    base_f = base.astype(np.float32) / 255.0
    dark_f = dark.astype(np.float32) / 255.0
    recovered = np.clip(dark_f**0.72 * 1.08, 0, 1)
    return to_u8(base_f * (1 - mask[..., None] * amount) + recovered * (mask[..., None] * amount))


def finish_real_estate(image: np.ndarray) -> np.ndarray:
    f = gray_world(image, 0.18).astype(np.float32) / 255.0
    y = 0.0722 * f[..., 0] + 0.7152 * f[..., 1] + 0.2126 * f[..., 2]

    lifted = np.clip(f**0.68, 0, 1)
    lift_mask = (1 - smoothstep(0.58, 0.94, y))[..., None]
    f = f * (1 - lift_mask * 0.52) + lifted * (lift_mask * 0.52)

    y = 0.0722 * f[..., 0] + 0.7152 * f[..., 1] + 0.2126 * f[..., 2]
    highlight = smoothstep(0.78, 1.0, y)[..., None]
    compressed = np.clip(f**1.10, 0, 1)
    f = f * (1 - highlight * 0.16) + compressed * (highlight * 0.16)

    f = np.clip((f - 0.5) * 1.03 + 0.5, 0, 1)
    out = to_u8(f)

    hsv = cv2.cvtColor(out, cv2.COLOR_BGR2HSV).astype(np.float32)
    hsv[..., 1] *= 1.035
    out = cv2.cvtColor(np.clip(hsv, 0, 255).astype(np.uint8), cv2.COLOR_HSV2BGR)

    blur = cv2.GaussianBlur(out.astype(np.float32), (0, 0), 1.0)
    out = np.clip(out.astype(np.float32) + (out.astype(np.float32) - blur) * 0.12, 0, 255).astype(np.uint8)
    return out


def correct_lens(image: np.ndarray, strength: float = 0.055) -> np.ndarray:
    h, w = image.shape[:2]
    camera = np.array([[w, 0, w / 2], [0, w, h / 2], [0, 0, 1]], dtype=np.float32)
    distortion = np.array([-strength, strength * 0.35, 0, 0, 0], dtype=np.float32)
    return cv2.undistort(image, camera, distortion)


SCENE_PROFILES = {
    "portrait": {"warmth": 0.050, "lift": 0.48, "highlight": 0.28, "contrast": 1.10, "local": 1.28, "vibrance": 0.22, "sharp": 0.13},
    "landscape": {"warmth": 0.018, "lift": 0.42, "highlight": 0.24, "contrast": 1.24, "local": 1.86, "vibrance": 0.44, "sharp": 0.22},
    "nature": {"warmth": 0.024, "lift": 0.44, "highlight": 0.24, "contrast": 1.20, "local": 1.78, "vibrance": 0.42, "sharp": 0.20},
    "interior": {"warmth": 0.034, "lift": 0.58, "highlight": 0.36, "contrast": 1.13, "local": 1.54, "vibrance": 0.24, "sharp": 0.16},
    "product": {"warmth": 0.012, "lift": 0.40, "highlight": 0.30, "contrast": 1.16, "local": 1.44, "vibrance": 0.28, "sharp": 0.18},
    "night": {"warmth": 0.030, "lift": 0.34, "highlight": 0.42, "contrast": 1.10, "local": 1.28, "vibrance": 0.30, "sharp": 0.10},
    "auto": {"warmth": 0.035, "lift": 0.50, "highlight": 0.30, "contrast": 1.16, "local": 1.62, "vibrance": 0.32, "sharp": 0.18},
}


def detect_scene_profile(rgb_float: np.ndarray, name: str = "") -> str:
    lower = name.lower()
    if re.search(r"(portrait|face|people|person|insan|portre|wedding|dugun)", lower):
        return "portrait"
    if re.search(r"(car|auto|vehicle|araba|otomobil)", lower):
        return "product"
    if re.search(r"(interior|estate|room|home|house|emlak|oda|icmekan)", lower):
        return "interior"
    if re.search(r"(landscape|sky|mountain|sea|city|manzara|deniz|dag)", lower):
        return "landscape"
    if re.search(r"(nature|forest|tree|flower|dogal|orman|agac)", lower):
        return "nature"
    if re.search(r"(night|dark|concert|gece)", lower):
        return "night"

    sample = rgb_float
    h, w = sample.shape[:2]
    scale = min(1.0, 520 / max(h, w))
    if scale < 1:
        sample = cv2.resize(sample, (round(w * scale), round(h * scale)), interpolation=cv2.INTER_AREA)

    rgb8 = to_u8(sample)
    bgr8 = rgb8[..., ::-1]
    hsv = cv2.cvtColor(bgr8, cv2.COLOR_BGR2HSV)
    hue = hsv[..., 0]
    sat = hsv[..., 1] / 255.0
    val = hsv[..., 2] / 255.0
    y = 0.2126 * sample[..., 0] + 0.7152 * sample[..., 1] + 0.0722 * sample[..., 2]
    upper = slice(0, max(1, sample.shape[0] // 2))

    sky = float(((hue[upper] >= 88) & (hue[upper] <= 124) & (sat[upper] > 0.20) & (val[upper] > 0.42)).mean())
    green = float(((hue >= 34) & (hue <= 88) & (sat > 0.24) & (val > 0.24)).mean())
    skin = float((((hue <= 18) | (hue >= 170)) & (sat > 0.14) & (sat < 0.68) & (val > 0.25)).mean())
    neutral = float((sat < 0.15).mean())
    dark = float((y < 0.20).mean())
    bright_bg = float(((y > 0.78) & (sat < 0.22)).mean())
    edges = cv2.Canny(cv2.cvtColor(bgr8, cv2.COLOR_BGR2GRAY), 80, 170)
    edge_density = float((edges > 0).mean())

    face_count = 0
    try:
        cascade_path = cv2.data.haarcascades + "haarcascade_frontalface_default.xml"
        detector = cv2.CascadeClassifier(cascade_path)
        if not detector.empty():
            faces = detector.detectMultiScale(cv2.cvtColor(bgr8, cv2.COLOR_BGR2GRAY), 1.12, 4, minSize=(36, 36))
            face_count = len(faces)
    except Exception:
        face_count = 0

    if face_count or skin > 0.075:
        return "portrait"
    if dark > 0.48 and float((y > 0.78).mean()) < 0.12:
        return "night"
    if sky > 0.10 and (green > 0.035 or edge_density > 0.045):
        return "landscape"
    if green > 0.12:
        return "nature"
    if neutral > 0.42 and edge_density > 0.055:
        return "interior"
    if bright_bg > 0.28 and edge_density < 0.075:
        return "product"
    return "auto"


def selective_scene_grade_bgr(image: np.ndarray, scene: str) -> np.ndarray:
    out = image
    hsv = cv2.cvtColor(out, cv2.COLOR_BGR2HSV).astype(np.float32)
    hue = hsv[..., 0]
    sat = hsv[..., 1]
    val = hsv[..., 2]

    if scene in {"landscape", "nature"}:
        sky = (hue >= 88) & (hue <= 124) & (sat > 38) & (val > 78)
        green = (hue >= 34) & (hue <= 88) & (sat > 38)
        hsv[..., 1][sky] = np.clip(hsv[..., 1][sky] * 1.10, 0, 255)
        hsv[..., 2][sky] = np.clip(hsv[..., 2][sky] * 0.97, 0, 255)
        hsv[..., 1][green] = np.clip(hsv[..., 1][green] * 1.08, 0, 255)
    elif scene == "portrait":
        skin = ((hue <= 18) | (hue >= 170)) & (sat > 28) & (sat < 174) & (val > 70)
        hsv[..., 1][skin] = np.clip(hsv[..., 1][skin] * 0.95, 0, 255)
        hsv[..., 2][skin] = np.clip(hsv[..., 2][skin] * 1.025, 0, 255)
    elif scene == "night":
        hsv[..., 1] = np.clip(hsv[..., 1] * 1.05, 0, 255)
        hsv[..., 2] = np.where(val < 72, np.clip(val * 0.96, 0, 255), val)

    out = cv2.cvtColor(np.clip(hsv, 0, 255).astype(np.uint8), cv2.COLOR_HSV2BGR)
    if scene == "night":
        out = cv2.bilateralFilter(out, 5, 28, 28)
    if scene in {"interior", "product"}:
        out = gray_world(out, 0.14 if scene == "interior" else 0.20)
    return out


def finish_raw_photo(rgb: np.ndarray, name: str = "") -> np.ndarray:
    f = rgb.astype(np.float32)
    if f.max() > 255:
        f /= 65535.0
    else:
        f /= 255.0

    f = np.clip(f, 0, 1)
    original = f.copy()
    scene = detect_scene_profile(original, name)
    profile = SCENE_PROFILES.get(scene, SCENE_PROFILES["auto"])
    f = auto_levels_rgb(f, 0.25, 99.82)
    f = original * 0.18 + f * 0.82

    warmth = profile["warmth"]
    f[..., 0] = np.clip(f[..., 0] * (1.02 + warmth) + 0.006, 0, 1)
    f[..., 1] = np.clip(f[..., 1] * 1.006 + 0.002, 0, 1)
    f[..., 2] = np.clip(f[..., 2] * (1.0 - warmth * 0.88), 0, 1)

    # Filmic shadow/highlight curve: opens dark RAW files while keeping bright windows usable.
    y = 0.2126 * f[..., 0] + 0.7152 * f[..., 1] + 0.0722 * f[..., 2]
    lifted = np.clip(f**0.64, 0, 1)
    lift_mask = (1 - smoothstep(0.30, 0.86, y))[..., None]
    f = f * (1 - lift_mask * profile["lift"]) + lifted * (lift_mask * profile["lift"])

    y = 0.2126 * f[..., 0] + 0.7152 * f[..., 1] + 0.0722 * f[..., 2]
    highlight = smoothstep(0.78, 1.0, y)[..., None]
    f = f * (1 - highlight * profile["highlight"]) + np.clip(f**1.22, 0, 1) * (highlight * profile["highlight"])

    y = 0.2126 * f[..., 0] + 0.7152 * f[..., 1] + 0.0722 * f[..., 2]
    s_curve = np.clip(0.5 + (f - 0.5) * profile["contrast"], 0, 1)
    mid_mask = smoothstep(0.16, 0.48, y) * (1 - smoothstep(0.78, 0.98, y))
    f = f * (1 - mid_mask[..., None] * 0.62) + s_curve * (mid_mask[..., None] * 0.62)

    out = to_u8(f[..., ::-1])
    out = gray_world(out, 0.10)
    out = local_contrast_bgr(out, profile["local"])
    out = cinematic_vibrance_bgr(out, profile["vibrance"])
    out = selective_scene_grade_bgr(out, scene)

    blur = cv2.GaussianBlur(out.astype(np.float32), (0, 0), 0.85)
    sharp = np.clip(out.astype(np.float32) + (out.astype(np.float32) - blur) * profile["sharp"], 0, 255).astype(np.uint8)
    return sharp


def convert_raw_photo(photo: PhotoFile) -> bytes:
    if re.search(r"\.(jpe?g|png|webp)$", photo.name, flags=re.I):
        image = decode_photo(photo)
        rgb = cv2.cvtColor(image, cv2.COLOR_BGR2RGB)
        image = finish_raw_photo(rgb, photo.name)
        ok, encoded = cv2.imencode(".jpg", image, [cv2.IMWRITE_JPEG_QUALITY, JPEG_QUALITY, cv2.IMWRITE_JPEG_OPTIMIZE, 1])
        if not ok:
            raise ValueError("JPG ciktisi olusturulamadi")
        return encoded.tobytes()

    suffix = Path(photo.name).suffix or ".raw"
    photo.storage.stream.seek(0)
    with tempfile.NamedTemporaryFile(suffix=suffix) as tmp:
        tmp.write(photo.storage.read())
        tmp.flush()
        with rawpy.imread(tmp.name) as raw:
            rgb = raw.postprocess(
                use_camera_wb=True,
                output_color=rawpy.ColorSpace.sRGB,
                output_bps=16,
                no_auto_bright=False,
                bright=1.0,
            )

    image = finish_raw_photo(rgb, photo.name)
    h, w = image.shape[:2]
    scale = min(1.0, MAX_SIDE / max(h, w))
    if scale < 1:
        image = cv2.resize(image, (round(w * scale), round(h * scale)), interpolation=cv2.INTER_AREA)

    ok, encoded = cv2.imencode(".jpg", image, [cv2.IMWRITE_JPEG_QUALITY, JPEG_QUALITY, cv2.IMWRITE_JPEG_OPTIMIZE, 1])
    if not ok:
        raise ValueError("RAW JPG ciktisi olusturulamadi")
    return encoded.tobytes()


def merge_real_estate(hdr_set: HdrSet, lens_correction: bool = False, shift_correction: bool = False) -> bytes:
    decoded = [decode_photo(hdr_set.low), decode_photo(hdr_set.mid), decode_photo(hdr_set.high)]
    dark, mid, bright = order_by_brightness(decoded)
    dark, mid, bright = match_dimensions([dark, mid, bright])
    dark, mid, bright = align_images([dark, mid, bright])
    dark, mid, bright = match_dimensions([dark, mid, bright])
    if shift_correction:
        dark, mid, bright = trim_shift_edges([dark, mid, bright])

    mertens = cv2.createMergeMertens(0.85, 0.08, 1.75)
    base = to_u8(mertens.process([dark, mid, bright]))
    base = blend_window(base, dark, mid, 0.86)
    final = finish_real_estate(base)
    if lens_correction:
        final = correct_lens(final)

    ok, encoded = cv2.imencode(".jpg", final, [cv2.IMWRITE_JPEG_QUALITY, JPEG_QUALITY, cv2.IMWRITE_JPEG_OPTIMIZE, 1])
    if not ok:
            raise ValueError("JPG ciktisi olusturulamadi")
    return encoded.tobytes()


@app.get("/colora-logo.png")
def colora_logo() -> Response:
    return Response(
        base64.b64decode(LOGO_PNG_B64),
        mimetype="image/png",
        headers={"Cache-Control": "public, max-age=31536000, immutable"},
    )


@app.get("/")
def index() -> Response:
    html = (APP_DIR / "index.html").read_text(encoding="utf-8")
    if 'rel="icon"' not in html:
        html = html.replace("</head>", '    <link rel="icon" type="image/png" href="/colora-logo.png" />\n  </head>')
    html = html.replace("</head>", '<style>.logo-mark{width:44px;height:44px;padding:3px;background:#fff;border:1px solid rgba(219,228,225,.92)}.logo-mark img{width:100%;height:100%;object-fit:contain;display:block}.brand span:last-child{font-weight:950;font-size:1.05rem}</style>\n  </head>')
    if 'id="lensCorrection"' not in html:
        controls = """
          <label class="toggle-control" for="lensCorrection">
            <span>
              <strong>Lens correction</strong>
              <small>Genis aci kenar egilmesini duzelt</small>
            </span>
            <input id="lensCorrection" type="checkbox" />
          </label>

          <label class="toggle-control" for="shiftCorrection">
            <span>
              <strong>Kayma duzeltme</strong>
              <small>Ust uste binme ve kenar kaymasini temizle</small>
            </span>
            <input id="shiftCorrection" type="checkbox" />
          </label>
"""
        html = html.replace('          <div class="action-row">', controls + '\n          <div class="action-row">')
    html = html.replace('src="app.js"', 'src="app.js?v=20260601-colora-ai1"')
    return Response(html, mimetype="text/html", headers={"Cache-Control": "no-store, max-age=0"})


@app.get("/<path:name>")
def assets(name: str) -> Response:
    if name == "app.js":
        script = (APP_DIR / "app.js").read_text(encoding="utf-8")
        match = re.search(r'atob\("([^"]+)"', script)
        if match:
            payload = match.group(1)
            payload += "=" * (-len(payload) % 4)
            script = base64.urlsafe_b64decode(payload).decode("utf-8")
        script = script.replace(
            'accept=".cr2,.cr3,.dng,.nef,.arw,.raf,.orf,.rw2,.pef,.srw,.raw"',
            'accept=".cr2,.cr3,.dng,.nef,.arw,.raf,.orf,.rw2,.pef,.srw,.raw,.jpg,.jpeg,.png,.webp,image/*"',
        )
        script = script.replace(
            'const rawOk = (f) => /\\.(cr2|cr3|dng|nef|arw|raf|orf|rw2|pef|srw|raw)$/i.test(f.name);',
            'const rawOk = (f) => f.type.startsWith("image/") || /\\.(cr2|cr3|dng|nef|arw|raf|orf|rw2|pef|srw|raw|jpe?g|png|webp)$/i.test(f.name);',
        )
        script = script.replace(
            "CR2, CR3, DNG, NEF, ARW ve benzeri RAW dosyalar\\u0131 \\u00e7oklu y\\u00fckle.",
            "CR2, CR3, DNG, NEF, ARW yan\\u0131nda JPG, PNG ve WebP dosyalar\\u0131n\\u0131 da \\u00e7oklu y\\u00fckle.",
        )
        script = script.replace(
            "Batch upload CR2, CR3, DNG, NEF, ARW and similar RAW files.",
            "Batch upload CR2, CR3, DNG, NEF, ARW plus JPG, PNG and WebP files.",
        )
        script = script.replace("Ayr\\u0131 RAW Auto ekran\\u0131", "Colora otomatik renk")
        script = script.replace("Separate RAW Auto workspace", "Colora auto color")
        script = script.replace(".raw-panel input[type=file]{display:block", ".raw-panel input[type=file]{display:none!important")
        return Response(script, mimetype="application/javascript", headers={"Cache-Control": "no-store, max-age=0"})

    response = send_from_directory(APP_DIR, name)
    response.headers["Cache-Control"] = "no-store, max-age=0"
    return response


@app.post("/api/merge")
def merge_endpoint() -> Response:
    uploads = request.files.getlist("photos")
    lens_correction = request.form.get("lens_correction") == "1"
    shift_correction = request.form.get("shift_correction") == "1"
    photos = [PhotoFile(file.filename or f"photo_{i}.jpg", file) for i, file in enumerate(uploads)]
    photos = [photo for photo in photos if photo.storage and photo.storage.filename]
    groups = group_photos(photos)

    if not groups:
        return jsonify({"error": "En az 3 fotograf yukle. Sira: low, middle, high."}), 400

    zip_buffer = io.BytesIO()
    with zipfile.ZipFile(zip_buffer, "w", zipfile.ZIP_DEFLATED, compresslevel=4) as archive:
        for index, hdr_set in enumerate(groups, start=1):
            try:
                result = merge_real_estate(hdr_set, lens_correction, shift_correction)
            except Exception as exc:
                app.logger.exception("HDR merge failed for %s", hdr_set.name)
                return jsonify({"error": f"{hdr_set.name} HDR merge hatasi: {exc}"}), 500
            archive.writestr(f"HDR_{index:04d}_{hdr_set.name}.jpg", result)

    zip_buffer.seek(0)
    return Response(
        zip_buffer.getvalue(),
        mimetype="application/zip",
        headers={"Content-Disposition": f'attachment; filename="real-estate-hdr-{len(groups)}-set.zip"'},
    )


@app.post("/api/raw")
def raw_endpoint() -> Response:
    uploads = request.files.getlist("raw_photos")
    photos = [PhotoFile(file.filename or f"raw_{i}.raw", file) for i, file in enumerate(uploads)]
    photos = [photo for photo in photos if photo.storage and photo.storage.filename]

    if not photos:
        return jsonify({"error": "En az 1 fotograf yukle."}), 400

    zip_buffer = io.BytesIO()
    with zipfile.ZipFile(zip_buffer, "w", zipfile.ZIP_DEFLATED, compresslevel=4) as archive:
        for index, photo in enumerate(sort_photos(photos), start=1):
            try:
                result = convert_raw_photo(photo)
            except Exception as exc:
                app.logger.exception("RAW conversion failed for %s", photo.name)
                return jsonify({"error": f"{photo.name} fotograf duzenleme hatasi: {exc}"}), 500
            name = scene_key(photo.name)
            archive.writestr(f"RAW_{index:04d}_{name}.jpg", result)

    zip_buffer.seek(0)
    return Response(
        zip_buffer.getvalue(),
        mimetype="application/zip",
        headers={"Content-Disposition": f'attachment; filename="raw-auto-edits-{len(photos)}-photo.zip"'},
    )


